# The Quest for Comprehensive Tests! The Grail of Quality Awaits!

Right then, knights! We must coordinate this testing quest with utmost precision. I am Arthur, King of the Britons, and I shall lead you through these trials!

```typescript
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { Checkout } from './Checkout';
import { CartProvider } from './CartContext';
import { PaymentProvider } from './PaymentContext';

// Mock context providers - we didn't vote for them, but we need them
const mockCart = {
  items: [{ id: '1', name: 'Holy Grail', price: 99.99 }],
  total: 99.99,
  clearCart: vi.fn()
};

const mockProcessPayment = vi.fn();

const renderCheckout = (props = {}) => {
  return render(
    <CartProvider value={mockCart}>
      <PaymentProvider value={{ processPayment: mockProcessPayment }}>
        <Checkout {...props} />
      </PaymentProvider>
    </CartProvider>
  );
};

describe('Checkout - The Holy Quest', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'GRAIL-001' });
  });

  // 1. Happy Path - Complete Checkout Flow
  describe('Complete Quest (Happy Path)', () => {
    it('should complete full checkout journey from shipping to confirmation', async () => {
      const user = userEvent.setup();
      const onComplete = vi.fn();
      renderCheckout({ onComplete });

      // Shipping step
      await user.type(screen.getByLabelText(/street address/i), '123 Camelot Lane');
      await user.type(screen.getByLabelText(/city/i), 'Camelot');
      await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
      await user.type(screen.getByLabelText(/zip code/i), '90210');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Payment step
      await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
      await user.type(screen.getByLabelText(/expiry/i), '12/25');
      await user.type(screen.getByLabelText(/cvv/i), '123');
      await user.type(screen.getByLabelText(/name on card/i), 'King Arthur');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Review step
      expect(screen.getByText(/holy grail/i)).toBeInTheDocument();
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Confirmation
      await waitFor(() => {
        expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
      });
      expect(onComplete).toHaveBeenCalledWith('GRAIL-001');
    });
  });

  // 2. Form Validation
  describe('Form Validation - Strange Women Distributing Errors', () => {
    it('should display error for empty street address', async () => {
      const user = userEvent.setup();
      renderCheckout();

      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByRole('alert')).toHaveTextContent(/street address is required/i);
    });

    it('should validate ZIP code format', async () => {
      const user = userEvent.setup();
      renderCheckout();

      await user.type(screen.getByLabelText(/zip code/i), 'NI!');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
    });
  });

  // 3. Edge Cases - Tis But a Scratch
  describe('Edge Cases', () => {
    it('should show empty cart message when no items', () => {
      mockCart.items = [];
      renderCheckout();

      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
    });
  });

  // 4. Accessibility - All Are Equal Before the Grail
  describe('Accessibility', () => {
    it('should have proper form labels and ARIA attributes', () => {
      renderCheckout();

      expect(screen.getByRole('form', { name: /shipping information/i })).toBeInTheDocument();
      expect(screen.getByRole('navigation', { name: /checkout progress/i })).toBeInTheDocument();
    });
  });
});
